package core

// Guidance describes implemented behavior, not parity with a commercial plugin.
type AppModuleGuidance struct {
	Description string   `json:"description"`
	Workflow    []string `json:"workflow"`
	Limitations []string `json:"limitations"`
}

func ModuleGuidance(id string) AppModuleGuidance {
	guides := map[string]AppModuleGuidance{
		"site-diagnosis":           {"检查真实网站的 DNS、HTTP、TLS、Nginx 配置及文件状态。", []string{"选择网站", "运行诊断", "按失败检查项排查"}, []string{"外部 DNS/TLS 受网络可达性影响；不会自动修改网站配置。"}},
		"network-threat-detection": {"读取真实监听端口、连接及 SSH 防暴力破解状态，对比端口基线。", []string{"确认正常端口后建立基线", "检查新增监听和公网暴露"}, []string{"端口变化检测不是流量包分析或完整 IDS；不会自动封禁新增端口。"}},
		"website-analytics":        {"独立浏览器采集与持久化统计，分析浏览量、浏览器访客、会话旅程、页面来源、点击坐标和页面性能。", []string{"选择网站并保存采集配置", "手动添加同源采集代理及 JS 标签", "在专用功能页查看真实采集数据"}, []string{"默认关闭；不自动修改网站或重载服务。浏览器标识不等于真实人数；不包含会话录像、地理数据库、INP 或完整转化漏斗。"}},
		"website-statistics-v2":    {"统计真实请求、流量、状态码、UTC 小时趋势，并定位错误及慢请求。", []string{"选择网站和时间范围", "按路径、IP、状态码或爬虫筛选", "查看错误与慢请求明细"}, []string{"读取当前日志末尾 16 MiB，不是全量历史数据库；不包含地理位置数据库。"}},
		"files-sync":               {"增量复制内容与权限，保护目标冲突；本机受管网站支持持久化同步计划与执行历史。", []string{"选择源和目标，先预览冲突与增量", "手动同步或保存 60–86400 秒的计划", "从计划列表暂停、恢复或手动执行，核对历史"}, []string{"不删除目标额外文件；跨服务器和实时监听尚未实现；隔离 PHP 项目仅手动同步。最多 32 个计划，历史保留最近 100 条；中断及连续失败会安全暂停。"}},
		"daily-report":             {"汇总真实系统资源、网站、任务、流量、安全状态及临期证书，保存每日报告。", []string{"刷新当日报告", "检查失败任务和即将到期证书"}, []string{"已支持后台每日生成；邮件、短信及其他外部推送尚未接入。"}},
		"enterprise-tamper-proof":  {"签名文件基线、持久化备份和定时篡改检测，可选择自动恢复已备份文件。", []string{"选择网站并配置自动恢复", "建立基线", "检查变更或恢复指定文件"}, []string{"这是周期检测和恢复，不是内核级写入拦截；新增文件不会自动删除，扫描受体积和文件数上限约束。"}},
		"load-balance":             {"配置真实 Nginx HTTP 上游、权重、备用节点、IP 粘滞与故障切换。", []string{"填写域名、回环入口端口和上游节点", "保存入口", "探测节点或移除入口"}, []string{"当前是 HTTP 回环入口，不含 TCP/UDP 均衡和外部告警。"}},
		"mobile-pwa":               {"通过移动布局、Web App Manifest 和 Service Worker 提供可安装的移动网页面板。", []string{"在浏览器打开面板", "使用添加到主屏幕", "沿用面板登录和权限"}, []string{"不是原生 iOS/Android 应用；不缓存账号或 API 数据。"}},
		"apache-waf":               {"将固定恶意 UA 与查询参数规则写入 Apache，配置检查后生效。", []string{"先安装 Apache 并绑定网站", "安装防护规则", "核对 Apache 语法与请求结果"}, []string{"基础规则防护，不包含完整 POST 请求体解析、地理封禁、动态规则引擎或完整攻击日志界面。"}},
		"php-code-security":        {"扫描网站 PHP 文件中的动态执行、命令执行、危险反序列化与文件写入风险。", []string{"选择网站", "执行扫描", "按文件、行号和规则审查代码"}, []string{"静态风险扫描不等于 PHP 内核运行时拦截；命中需要人工判断，不自动隔离或删除代码。"}},
		"task-manager":             {"查看真实进程 CPU、内存、磁盘 I/O 与连接；通过进程身份校验终止受管进程。", []string{"刷新进程列表", "按 CPU、内存或 I/O 排序", "选择可终止的受管进程"}, []string{"只允许 SIGTERM 非 root 的云栈受管进程；不会终止系统关键进程或任意进程树。"}},
		"website-tamper-proof":     {"建立签名文件基线，检测新增、删除、内容及权限变化，支持指定文件恢复。", []string{"选择网站建立基线", "查看变更记录", "选择基线文件恢复"}, []string{"定时检测，不是内核级实时拦截；扫描上限 10000 文件、单文件 8 MiB、总计 256 MiB。"}},
		"user-manager":             {"创建和管理真实面板用户、管理员/操作员/只读角色、网站范围与会话撤销。", []string{"刷新用户列表", "选择用户或填写新用户名", "设置角色和网站范围后保存"}, []string{"采用角色与网站范围授权，不包含独立菜单权限、套餐或计费功能。"}},
		"file-monitor":             {"按排除规则建立签名基线，后台检测文件和权限变化，支持策略暂停、恢复及有界历史。", []string{"选择网站、排除路径与 60–86400 秒检测间隔", "建立监控基线", "从策略列表暂停或恢复，核对自动检测历史"}, []string{"周期扫描，不是实时 inotify；尚无外部告警；每个应用最多 100 个基线，历史保留最近 100 条；签名错误或连续失败停止自动保护。"}},
		"disk-analysis":            {"统计网站目录真实文件大小、子目录分布、扩展名分布和最大文件，支持子目录扫描。", []string{"选择网站或网站内子目录", "扫描占用", "从目录分布或大文件所在目录继续下钻"}, []string{"仅扫描网站 public 目录，最多 100000 个目录/文件；分类和长路径达到报告上限时会标记部分结果，不扫描任意系统路径、不自动删除文件。"}},
		"platform-ops":             {"使用独立可撤销令牌和可信 HTTPS 聚合多个云栈主机的真实运行状态。", []string{"在被管理面板生成只读令牌", "添加 HTTPS 主机", "刷新聚合状态或撤销授权"}, []string{"当前是只读监控，不提供远程批量命令、补丁发布或任意 SSH 操作。"}},
		"nfs-manager":              {"将真实 NFS 共享挂载到受管目录，保留挂载策略并在重启后恢复。", []string{"填写挂载标识和服务端导出路径", "选择只读策略并挂载", "核对状态或卸载"}, []string{"当前是 NFS 客户端管理，不包含服务端导出配置。"}},
		"pm2-manager":              {"用真实 PM2 管理非 root 网站 Node.js 程序，支持启动、停止、重启、日志和删除。", []string{"选择网站并准备 JS 入口", "填写应用标识与回环端口", "创建后从列表选择项目操作"}, []string{"不接受任意 shell 命令；当前不提供 PM2 集群模式或在线 npm 依赖编辑。"}},
		"pure-ftpd":                {"创建真实 FTP 虚拟用户，TLS 连接并限制在对应网站目录，支持用户删除。", []string{"选择网站并创建 FTP 用户", "使用 FTPS 连接受管服务", "从列表选择用户管理"}, []string{"默认回环监听；外部 FTPS、被动端口和安全组需独立配置，不擅自暴露到公网。"}},
	}
	return guides[id]
}
